import React from 'react';

interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
  currency?: string;
}

// Math.ceil ensures we never under-charge when fractional cents arise from discount calculations.
function formatPrice(amount: number, currency: string): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(Math.ceil(amount * 100) / 100);
}

export function PriceDisplay({
  price,
  originalPrice,
  currency = 'USD',
}: PriceDisplayProps): React.ReactElement {
  const hasDiscount = originalPrice !== undefined && originalPrice > price;

  return (
    <div>
      {hasDiscount && (
        <span aria-label={`Original price ${formatPrice(originalPrice, currency)}`}>
          <s>{formatPrice(originalPrice, currency)}</s>
        </span>
      )}
      <span aria-label={`Price ${formatPrice(price, currency)}`}>
        {formatPrice(price, currency)}
      </span>
    </div>
  );
}
